const fs = require('fs');
const path = require('path');

const dir = __dirname;
const readme = fs.readFileSync(path.join(dir, 'README.md'), 'utf8');

const headings = readme
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'));

fs.writeFileSync(path.join(dir, 'INDEX.md'), headings.join('\n') + (headings.length ? '\n' : ''));

console.log(`Wrote ${headings.length} heading(s) to INDEX.md`);

